"""Verify the fast scanner is exact on valid JSON documents of many depths."""
import json, random, sys
sys.path.insert(0, '/workspace/submission')
import main as M

def true_depth_ok(text):
    """Reference: iterate characters, tracking whether we are inside a JSON string."""
    depth, instr, esc = 0, False, False
    for ch in text:
        if instr:
            if esc: esc = False
            elif ch == '\\': esc = True
            elif ch == '"': instr = False
            continue
        if ch == '"': instr = True
        elif ch in '[{':
            depth += 1
            if depth > M.MAX_DEPTH: return False
        elif ch in ']}': depth -= 1
    return True

ok = True
# container depth counting: root object is depth 1
for extra in range(0, 8):
    for mode in ('arr', 'obj'):
        depth_total = 1 + extra
        if mode == 'arr':
            raw = ('{"zones":' + '[' * extra + ']' * extra + ',"profiles":[{"id":"p",'
                   '"max_aliases":4,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}')
        else:
            raw = ('{"zones":' + '{"x":' * extra + '{}' + '}' * extra +
                   ',"profiles":[{"id":"p","max_aliases":4,"cname":"follow",'
                   '"wildcard":"rfc"}],"queries":[],"observations":[]}')
        valid = json.loads(raw)        # must be valid JSON
        expect = depth_total <= M.MAX_DEPTH
        got = M.nesting_within_limit(raw.encode())
        if got != expect:
            ok = False
            print('BAD: extra=%d mode=%s total=%d got=%s expect=%s' % (extra, mode, depth_total, got, expect))
print('valid-JSON depth boundaries exact:', ok)

# randomised valid JSON documents: scanner must never reject them
rng = random.Random(31337)
def rnd_value(rng, depth):
    if depth == 0:
        return rng.choice([1, -2, 0, 'txt', 'a"b', 'back\\slash', '[bracket]', '{brace}', '',
                           '\\u0022q', 'x' * 40, 3.5, None, True, 'tab\\there'])
    kind = rng.randrange(4)
    if kind == 0:
        return [rnd_value(rng, depth - 1) for _ in range(rng.randint(0, 3))]
    if kind == 1:
        return {str(i): rnd_value(rng, depth - 1) for i in range(rng.randint(0, 3))}
    if kind == 2:
        return rng.choice([1, 'str', None])
    return [rng.choice(['"', '\\', '}', '{', ']', '[']) for _ in range(rng.randint(0, 5))]
bad = 0
for i in range(30000):
    doc = {'zones': [rnd_value(rng, 3)], 'profiles': [{'id': 'p', 'max_aliases': 2,
           'cname': 'follow', 'wildcard': 'rfc'}], 'queries': [], 'observations': []}
    raw = json.dumps(doc)
    json.loads(raw)
    if not M.nesting_within_limit(raw.encode()):
        bad += 1
        if bad < 3:
            print('FALSE REJECTION at trial %d: %r' % (i, raw[:120]))
print('false rejections on %d random valid documents: %d' % (30000, bad))
PYEOF
